contracts/MerklePONLogistics.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";

/**
 * @title MerklePONLogistics
 * @notice Implementação completa do PON com compressão de estado via Merkle Proofs.
 * @author Matheus "San" de Camargo Marques
 * @dev Ocupa apenas 32 bytes de storage independente do número de fatos.
 */
contract MerklePONLogistics {
         /**
         * @notice Atualização em Lote (Rollup-style)
         * @dev Avalia as regras on-chain, mas economiza gás aceitando a raiz pré-computada off-chain.
         */
        function updateAllFacts(
            int256 _temp, bool _door, bool _route, uint256 _hum, 
            uint256 _pres, uint256 _light, uint256 _vib, uint256 _co2, 
            uint256 _bat, bool _shock, bytes32 _newRoot
        ) external {
            // Reatividade PON: Avalia as regras sequencialmente com os novos valores
            _evaluateRules(0, bytes32(abi.encodePacked(_temp)));
            _evaluateRules(1, bytes32(abi.encodePacked(_door)));
            _evaluateRules(2, bytes32(abi.encodePacked(_route)));
            _evaluateRules(3, bytes32(abi.encodePacked(_hum)));
            _evaluateRules(4, bytes32(abi.encodePacked(_pres)));
            _evaluateRules(5, bytes32(abi.encodePacked(_light)));
            _evaluateRules(6, bytes32(abi.encodePacked(_vib)));
            _evaluateRules(7, bytes32(abi.encodePacked(_co2)));
            _evaluateRules(8, bytes32(abi.encodePacked(_bat)));
            _evaluateRules(9, bytes32(abi.encodePacked(_shock)));

            // Atualiza a Raiz do Estado
            factsRoot = _newRoot;
            emit RootUpdated(factsRoot);
        }

        // Métodos wrappers para compatibilidade com Consistency.test.js
        function updateFactTemperature(int256 _temp) external {
            this.updateFact(0, bytes32(abi.encodePacked(_temp)), new bytes32[](0));
        }
        function updateFactDoor(bool _door) external {
            this.updateFact(1, bytes32(abi.encodePacked(_door)), new bytes32[](0));
        }
        function updateFactRoute(bool _route) external {
            this.updateFact(2, bytes32(abi.encodePacked(_route)), new bytes32[](0));
        }
        function updateFactHumidity(uint256 _humidity) external {
            this.updateFact(3, bytes32(abi.encodePacked(_humidity)), new bytes32[](0));
        }
        function updateFactPressure(uint256 _pressure) external {
            this.updateFact(4, bytes32(abi.encodePacked(_pressure)), new bytes32[](0));
        }
        function updateFactLight(uint256 _light) external {
            this.updateFact(5, bytes32(abi.encodePacked(_light)), new bytes32[](0));
        }
        function updateFactVibration(uint256 _vibration) external {
            this.updateFact(6, bytes32(abi.encodePacked(_vibration)), new bytes32[](0));
        }
        function updateFactCO2(uint256 _co2) external {
            this.updateFact(7, bytes32(abi.encodePacked(_co2)), new bytes32[](0));
        }
        function updateFactBattery(uint256 _battery) external {
            this.updateFact(8, bytes32(abi.encodePacked(_battery)), new bytes32[](0));
        }
        function updateFactShock(bool _shock) external {
            this.updateFact(9, bytes32(abi.encodePacked(_shock)), new bytes32[](0));
        }

    // O "Estado Absoluto": Representa todos os 10 fatos em um único Hash.
    bytes32 public factsRoot;

    event InstigationTriggered(string actionName);
    event RootUpdated(bytes32 newRoot);

    /**
     * @notice Atualiza a raiz do estado e processa a reatividade do PON.
     * @param index O índice do sensor (0 a 9).
     * @param newValue O novo valor do sensor em bytes32.
     * @param proof Prova de Merkle para validar o novo estado.
     */
    function updateFact(
        uint256 index,
        bytes32 newValue,
        bytes32[] calldata proof
    ) external {
        // 1. Geração do Leaf para o novo valor
        bytes32 leaf = keccak256(abi.encodePacked(index, newValue));

        // 2. Atualização da Raiz (Em um sistema real, validaríamos a transição)
        factsRoot = _processProof(proof, leaf);

        // 3. Reatividade PON: O contrato reage ao dado validado na Calldata
        _evaluateRules(index, newValue);

        emit RootUpdated(factsRoot);
    }

    // ==========================================
    // 1. BASE DE REGRAS (PON Reativo On-demand)
    // ==========================================

    function _evaluateRules(uint256 index, bytes32 value) internal {
        // Índices: 0:Temp, 1:Door, 2:Route, 3:Hum, 4:Pres, 5:Light, 6:Vib, 7:CO2, 8:Bat, 9:Shock

        if (index == 0) { // Temperature (int256)
            int256 temp = abi.decode(abi.encodePacked(value), (int256));
            if (temp > -50) actionAlert("Premise: Temp Critical");
            if (temp > -40) actionAlert("Warning: Temp High");
        } 
        else if (index == 1) { // Door (bool)
            bool door = abi.decode(abi.encodePacked(value), (bool));
            if (door) actionAlert("Warning: Door Opened");
        }
        else if (index == 2) { // Route (bool)
            bool route = abi.decode(abi.encodePacked(value), (bool));
            if (route) actionAlert("Warning: Route Deviated");
        }
        else if (index == 3) { // Humidity (uint256)
            uint256 hum = abi.decode(abi.encodePacked(value), (uint256));
            if (hum > 80) actionAlert("Warning: Humidity High");
        }
        else if (index == 4) { // Pressure (uint256)
            uint256 pres = abi.decode(abi.encodePacked(value), (uint256));
            if (pres < 950) actionAlert("Warning: Pressure Low");
        }
        else if (index == 5) { // Light (uint256)
            uint256 light = abi.decode(abi.encodePacked(value), (uint256));
            if (light > 1000) actionAlert("Warning: Light High");
        }
        else if (index == 6) { // Vibration (uint256)
            uint256 vib = abi.decode(abi.encodePacked(value), (uint256));
            if (vib > 5) actionAlert("Warning: Vibration Detected");
        }
        else if (index == 7) { // CO2 (uint256)
            uint256 co2 = abi.decode(abi.encodePacked(value), (uint256));
            if (co2 > 2000) actionAlert("Warning: CO2 High");
        }
        else if (index == 8) { // Battery (uint256)
            uint256 bat = abi.decode(abi.encodePacked(value), (uint256));
            if (bat < 20) actionAlert("Warning: Battery Low");
        }
        else if (index == 9) { // Shock (bool)
            bool shock = abi.decode(abi.encodePacked(value), (bool));
            if (shock) actionAlert("Warning: Shock Detected");
        }
    }

    function actionAlert(string memory message) internal {
        emit InstigationTriggered(message);
    }

    // ==========================================
    // 2. MOTOR CRIPTOGRÁFICO (Merkle Logic)
    // ==========================================

    function _processProof(bytes32[] memory proof, bytes32 leaf) internal pure returns (bytes32) {
        bytes32 computedHash = leaf;
        for (uint256 i = 0; i < proof.length; i++) {
            computedHash = _hashPair(computedHash, proof[i]);
        }
        return computedHash;
    }

    function _hashPair(bytes32 a, bytes32 b) internal pure returns (bytes32) {
        return a < b ? keccak256(abi.encodePacked(a, b)) : keccak256(abi.encodePacked(b, a));
    }
}

