// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract ParadigmaticPONLogistics {

    // ==========================================
    // 1. BASE DE FATOS (Fact Base - FB)
    // ==========================================

    // --- FBEs: Atributos (Attributes) ---
    int256 private attributeTemperature;
    bool private attributeDoorOpen;
    bool private attributeRouteDeviated;
    int256 private attributeHumidity;
    int256 private attributePressure;
    int256 private attributeLight;
    int256 private attributeVibration;
    int256 private attributeCO2;
    int256 private attributeBattery;
    bool private attributeShockDetected;

    event InstigationTriggered(string actionName);

    /**
     * @notice Recebe múltiplos fatos em uma única transação, mas mantém
     * o roteamento estrito do PON (Atributo -> Premissa).
     */
    function methodUpdateAll(
        int256 _temp, bool _door, bool _route, int256 _humidity, 
        int256 _pressure, int256 _light, int256 _vibration, 
        int256 _co2, int256 _battery, bool _shock
    ) external {

        if (attributeTemperature != _temp) {
            attributeTemperature = _temp;
            premiseTempCritical();
            premiseTempHigh();
        }

        if (attributeDoorOpen != _door) {
            attributeDoorOpen = _door;
            premiseDoorOpen();
        }

        if (attributeRouteDeviated != _route) {
            attributeRouteDeviated = _route;
            premiseRouteDeviated();
        }

        if (attributeHumidity != _humidity) {
            attributeHumidity = _humidity;
            premiseHumidityHigh();
        }

        if (attributePressure != _pressure) {
            attributePressure = _pressure;
            premisePressureLow();
        }

        if (attributeLight != _light) {
            attributeLight = _light;
            premiseLightHigh();
        }

        if (attributeVibration != _vibration) {
            attributeVibration = _vibration;
            premiseVibrationDetected();
        }

        if (attributeCO2 != _co2) {
            attributeCO2 = _co2;
            premiseCO2High();
        }

        if (attributeBattery != _battery) {
            attributeBattery = _battery;
            premiseBatteryLow();
        }

        if (attributeShockDetected != _shock) {
            attributeShockDetected = _shock;
            premiseShockDetected();
        }
    }

    // --- FBEs: Métodos (Methods) ---
    function methodUpdateTemperature(int256 _temp) external {
        if (attributeTemperature != _temp) {
            attributeTemperature = _temp;
            premiseTempCritical();
            premiseTempHigh();
        }
    }

    function methodUpdateDoor(bool _door) external {
        if (attributeDoorOpen != _door) {
            attributeDoorOpen = _door;
            premiseDoorOpen();
        }
    }

    function methodUpdateRoute(bool _route) external {
        if (attributeRouteDeviated != _route) {
            attributeRouteDeviated = _route;
            premiseRouteDeviated();
        }
    }

    function methodUpdateHumidity(int256 _humidity) external {
        if (attributeHumidity != _humidity) {
            attributeHumidity = _humidity;
            premiseHumidityHigh();
        }
    }

    function methodUpdatePressure(int256 _pressure) external {
        if (attributePressure != _pressure) {
            attributePressure = _pressure;
            premisePressureLow();
        }
    }

    function methodUpdateLight(int256 _light) external {
        if (attributeLight != _light) {
            attributeLight = _light;
            premiseLightHigh();
        }
    }

    function methodUpdateVibration(int256 _vibration) external {
        if (attributeVibration != _vibration) {
            attributeVibration = _vibration;
            premiseVibrationDetected();
        }
    }

    function methodUpdateCO2(int256 _co2) external {
        if (attributeCO2 != _co2) {
            attributeCO2 = _co2;
            premiseCO2High();
        }
    }

    function methodUpdateBattery(int256 _battery) external {
        if (attributeBattery != _battery) {
            attributeBattery = _battery;
            premiseBatteryLow();
        }
    }

    function methodUpdateShock(bool _shock) external {
        if (attributeShockDetected != _shock) {
            attributeShockDetected = _shock;
            premiseShockDetected();
        }
    }


    // ==========================================
    // 2. BASE DE REGRAS (Rule Base - RB)
    // ==========================================

    // --- Premissas (Premises) ---
    function premiseTempCritical() internal {
        if (attributeTemperature > -50) {
            conditionTempAndDoor();
        }
    }

    function premiseTempHigh() internal {
        if (attributeTemperature > -40) {
            conditionTempHigh();
        }
    }

    function premiseDoorOpen() internal {
        if (attributeDoorOpen == true) {
            conditionTempAndDoor();
        }
    }

    function premiseRouteDeviated() internal {
        if (attributeRouteDeviated == true) {
            conditionRouteDeviated();
        }
    }

    function premiseHumidityHigh() internal {
        if (attributeHumidity > 80) {
            conditionHumidityHigh();
        }
    }

    function premisePressureLow() internal {
        if (attributePressure < 950) {
            conditionPressureLow();
        }
    }

    function premiseLightHigh() internal {
        if (attributeLight > 1000) {
            conditionLightHigh();
        }
    }

    function premiseVibrationDetected() internal {
        if (attributeVibration > 5) {
            conditionVibrationDetected();
        }
    }

    function premiseCO2High() internal {
        if (attributeCO2 > 2000) {
            conditionCO2High();
        }
    }

    function premiseBatteryLow() internal {
        if (attributeBattery < 20) {
            conditionBatteryLow();
        }
    }

    function premiseShockDetected() internal  {
        if (attributeShockDetected == true) {
            conditionShockDetected();
        }
    }

    // --- Condições (Conditions) ---
    function conditionTempAndDoor() internal  {
        if (attributeTemperature > -50 && attributeDoorOpen) {
            ruleCriticalViolation();
        }
    }

    function conditionTempHigh() internal  {
        ruleWarningTemp();
    }

    function conditionRouteDeviated() internal {
        ruleWarningRoute();
    }

    function conditionHumidityHigh() internal  {
        ruleWarningHumidity();
    }

    function conditionPressureLow() internal {
        ruleWarningPressure();
    }

    function conditionLightHigh() internal  {
        ruleWarningLight();
    }

    function conditionVibrationDetected() internal  {
        ruleWarningVibration();
    }

    function conditionCO2High() internal  {
        ruleWarningCO2();
    }

    function conditionBatteryLow() internal  {
        ruleWarningBattery();
    }

    function conditionShockDetected() internal {
        ruleWarningShock();
    }

    // --- Regras (Rules) ---
    function ruleCriticalViolation() internal {
        actionAlertCritical();
    }

    function ruleWarningTemp() internal {
        actionAlertTemp();
    }

    function ruleWarningRoute() internal {
        actionAlertRoute();
    }

    function ruleWarningHumidity() internal {
        actionAlertHumidity();
    }

    function ruleWarningPressure() internal {
        actionAlertPressure();
    }

    function ruleWarningLight() internal {
        actionAlertLight();
    }

    function ruleWarningVibration() internal {
        actionAlertVibration();
    }

    function ruleWarningCO2() internal {
        actionAlertCO2();
    }

    function ruleWarningBattery() internal {
        actionAlertBattery();
    }

    function ruleWarningShock() internal {
        actionAlertShock();
    }

    // --- Ações (Actions) e Instigações (Instigations) ---
    function actionAlertCritical() internal {
        instigationEmitEvent("Critical: Temp high and door open");
    }

    function actionAlertTemp() internal {
        instigationEmitEvent("Warning: Temp too high");
    }

    function actionAlertRoute() internal {
        instigationEmitEvent("Warning: Route deviated");
    }

    function actionAlertHumidity() internal {
        instigationEmitEvent("Warning: Humidity too high");
    }

    function actionAlertPressure() internal {
        instigationEmitEvent("Warning: Pressure too low");
    }

    function actionAlertLight() internal {
        instigationEmitEvent("Warning: Light too high");
    }

    function actionAlertVibration() internal {
        instigationEmitEvent("Warning: Vibration detected");
    }

    function actionAlertCO2() internal {
        instigationEmitEvent("Warning: CO2 too high");
    }

    function actionAlertBattery() internal {
        instigationEmitEvent("Warning: Battery low");
    }

    function actionAlertShock() internal {
        instigationEmitEvent("Warning: Shock detected");
    }

    function instigationEmitEvent(string memory message) internal {
        emit InstigationTriggered(message);
    }
}

contracts/PONBitPackedLogistics.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title PONBitPackedLogistics
 * @author Matheus "San" de Camargo Marques
 * @notice Implementação de Alto Desempenho do PON com Empacotamento de Bits (Bit-Packing)
 */
contract PONBitPackedLogistics {
    // Único slot de 256 bits para o estado global (State Footprint Mínimo)
    uint256 private packedFacts;

    // --- Mapa de Offsets (Posicionamento dos Fatos no Bitfield) ---
    uint256 private constant OFF_TEMP    = 0;   // 8 bits (int8)
    uint256 private constant OFF_DOOR    = 8;   // 1 bit  (bool)
    uint256 private constant OFF_ROUTE   = 9;   // 1 bit  (bool)
    uint256 private constant OFF_HUM     = 10;  // 8 bits (uint8)
    uint256 private constant OFF_PRES    = 18;  // 16 bits (uint16)
    uint256 private constant OFF_LIGHT   = 34;  // 16 bits (uint16)
    uint256 private constant OFF_VIB     = 50;  // 8 bits (uint8)
    uint256 private constant OFF_CO2     = 58;  // 16 bits (uint16)
    uint256 private constant OFF_BAT     = 74;  // 8 bits (uint8)
    uint256 private constant OFF_SHOCK   = 82;  // 1 bit  (bool)

    event InstigationTriggered(string actionName);

    // ==========================================
    // 3. ATUALIZAÇÃO EM LOTE (Batch Update)
    // ==========================================

    /**
     * @notice Atualiza todos os 10 sensores em uma única transação usando Solidity puro.
     * @dev Isola o ganho de eficiência do Storage (1 SSTORE) do ganho de processamento.
     */
    function updateAllBitPacked(
        int8 _temp, bool _door, bool _route, uint8 _hum, 
        uint16 _pres, uint16 _light, uint8 _vib, uint16 _co2, 
        uint8 _bat, bool _shock
    ) external {
        uint256 currentPacked = packedFacts;
        uint256 newPacked = currentPacked;
        bool hasChanges = false;

        // --- 1. DETECÇÃO DE DELTA E EMPACOTAMENTO EM MEMÓRIA ---

        // Temp
        int8 cTemp = int8(uint8((currentPacked >> OFF_TEMP) & 0xFF));
        bool tempChanged = (cTemp != _temp);
        if (tempChanged) {
            newPacked = (newPacked & ~(uint256(0xFF) << OFF_TEMP)) | (uint256(uint8(_temp)) << OFF_TEMP);
            hasChanges = true;
        }

        // Door
        bool cDoor = ((currentPacked >> OFF_DOOR) & 1) == 1;
        bool doorChanged = (cDoor != _door);
        if (doorChanged) {
            if (_door) newPacked |= (1 << OFF_DOOR);
            else newPacked &= ~(1 << OFF_DOOR);
            hasChanges = true;
        }

        // Route
        bool cRoute = ((currentPacked >> OFF_ROUTE) & 1) == 1;
        bool routeChanged = (cRoute != _route);
        if (routeChanged) {
            if (_route) newPacked |= (1 << OFF_ROUTE);
            else newPacked &= ~(1 << OFF_ROUTE);
            hasChanges = true;
        }

        // Humidity
        uint8 cHum = uint8((currentPacked >> OFF_HUM) & 0xFF);
        bool humChanged = (cHum != _hum);
        if (humChanged) {
            newPacked = (newPacked & ~(uint256(0xFF) << OFF_HUM)) | (uint256(_hum) << OFF_HUM);
            hasChanges = true;
        }

        // Pressure
        uint16 cPres = uint16((currentPacked >> OFF_PRES) & 0xFFFF);
        bool presChanged = (cPres != _pres);
        if (presChanged) {
            newPacked = (newPacked & ~(uint256(0xFFFF) << OFF_PRES)) | (uint256(_pres) << OFF_PRES);
            hasChanges = true;
        }

        // Light
        uint16 cLight = uint16((currentPacked >> OFF_LIGHT) & 0xFFFF);
        bool lightChanged = (cLight != _light);
        if (lightChanged) {
            newPacked = (newPacked & ~(uint256(0xFFFF) << OFF_LIGHT)) | (uint256(_light) << OFF_LIGHT);
            hasChanges = true;
        }

        // Vibration
        uint8 cVib = uint8((currentPacked >> OFF_VIB) & 0xFF);
        bool vibChanged = (cVib != _vib);
        if (vibChanged) {
            newPacked = (newPacked & ~(uint256(0xFF) << OFF_VIB)) | (uint256(_vib) << OFF_VIB);
            hasChanges = true;
        }

        // CO2
        uint16 cCO2 = uint16((currentPacked >> OFF_CO2) & 0xFFFF);
        bool co2Changed = (cCO2 != _co2);
        if (co2Changed) {
            newPacked = (newPacked & ~(uint256(0xFFFF) << OFF_CO2)) | (uint256(_co2) << OFF_CO2);
            hasChanges = true;
        }

        // Battery
        uint8 cBat = uint8((currentPacked >> OFF_BAT) & 0xFF);
        bool batChanged = (cBat != _bat);
        if (batChanged) {
            newPacked = (newPacked & ~(uint256(0xFF) << OFF_BAT)) | (uint256(_bat) << OFF_BAT);
            hasChanges = true;
        }

        // Shock
        bool cShock = ((currentPacked >> OFF_SHOCK) & 1) == 1;
        bool shockChanged = (cShock != _shock);
        if (shockChanged) {
            if (_shock) newPacked |= (1 << OFF_SHOCK);
            else newPacked &= ~(1 << OFF_SHOCK);
            hasChanges = true;
        }

        // --- 2. PERSISTÊNCIA ATÔMICA ---
        // Apenas 1 SSTORE se houver qualquer mutação
        if (hasChanges) {
            packedFacts = newPacked;
        }

        // --- 3. MOTOR DE INFERÊNCIA REATIVO (Roteamento PON) ---
        // Disparamos as regras EXCLUSIVAMENTE baseadas nos deltas

        if (tempChanged) {
            premiseTempCritical(_temp);
            premiseTempHigh(_temp);
        }
        if (doorChanged) {
            premiseDoorOpen(_door);
        }
        if (routeChanged) {
            conditionRouteDeviated(_route);
        }
        if (humChanged) {
            conditionHumidityHigh(_hum);
        }
        if (presChanged) {
            conditionPressureLow(_pres);
        }
        if (lightChanged) {
            conditionLightHigh(_light);
        }
        if (vibChanged) {
            conditionVibrationDetected(_vib);
        }
        if (co2Changed) {
            conditionCO2High(_co2);
        }
        if (batChanged) {
            conditionBatteryLow(_bat);
        }
        if (shockChanged) {
            conditionShockDetected(_shock);
        }
    }
    // ==========================================
    // 1. BASE DE FATOS (FBE - Fact Base Elements)
    // ==========================================

    function methodUpdateTemperature(int8 _temp) external {
        int8 current = int8(uint8((packedFacts >> OFF_TEMP) & 0xFF));
        if (current != _temp) {
            packedFacts = (packedFacts & ~(uint256(0xFF) << OFF_TEMP)) | (uint256(uint8(_temp)) << OFF_TEMP);
            premiseTempCritical(_temp);
            premiseTempHigh(_temp);
        }
    }

    function methodUpdateDoor(bool _door) external {
        bool current = ((packedFacts >> OFF_DOOR) & 1) == 1;
        if (current != _door) {
            if (_door) packedFacts |= (1 << OFF_DOOR);
            else packedFacts &= ~(1 << OFF_DOOR);
            premiseDoorOpen(_door);
        }
    }

    function methodUpdateRoute(bool _route) external {
        bool current = ((packedFacts >> OFF_ROUTE) & 1) == 1;
        if (current != _route) {
            if (_route) packedFacts |= (1 << OFF_ROUTE);
            else packedFacts &= ~(1 << OFF_ROUTE);
            conditionRouteDeviated(_route);
        }
    }

    function methodUpdateHumidity(uint8 _hum) external {
        uint8 current = uint8((packedFacts >> OFF_HUM) & 0xFF);
        if (current != _hum) {
            packedFacts = (packedFacts & ~(uint256(0xFF) << OFF_HUM)) | (uint256(_hum) << OFF_HUM);
            conditionHumidityHigh(_hum);
        }
    }

    function methodUpdatePressure(uint16 _pres) external {
        uint16 current = uint16((packedFacts >> OFF_PRES) & 0xFFFF);
        if (current != _pres) {
            packedFacts = (packedFacts & ~(uint256(0xFFFF) << OFF_PRES)) | (uint256(_pres) << OFF_PRES);
            conditionPressureLow(_pres);
        }
    }

    function methodUpdateLight(uint16 _light) external {
        uint16 current = uint16((packedFacts >> OFF_LIGHT) & 0xFFFF);
        if (current != _light) {
            packedFacts = (packedFacts & ~(uint256(0xFFFF) << OFF_LIGHT)) | (uint256(_light) << OFF_LIGHT);
            conditionLightHigh(_light);
        }
    }

    function methodUpdateVibration(uint8 _vib) external {
        uint8 current = uint8((packedFacts >> OFF_VIB) & 0xFF);
        if (current != _vib) {
            packedFacts = (packedFacts & ~(uint256(0xFF) << OFF_VIB)) | (uint256(_vib) << OFF_VIB);
            conditionVibrationDetected(_vib);
        }
    }

    function methodUpdateCO2(uint16 _co2) external {
        uint16 current = uint16((packedFacts >> OFF_CO2) & 0xFFFF);
        if (current != _co2) {
            packedFacts = (packedFacts & ~(uint256(0xFFFF) << OFF_CO2)) | (uint256(_co2) << OFF_CO2);
            conditionCO2High(_co2);
        }
    }

    function methodUpdateBattery(uint8 _bat) external {
        uint8 current = uint8((packedFacts >> OFF_BAT) & 0xFF);
        if (current != _bat) {
            packedFacts = (packedFacts & ~(uint256(0xFF) << OFF_BAT)) | (uint256(_bat) << OFF_BAT);
            conditionBatteryLow(_bat);
        }
    }

    function methodUpdateShock(bool _shock) external {
        bool current = ((packedFacts >> OFF_SHOCK) & 1) == 1;
        if (current != _shock) {
            if (_shock) packedFacts |= (1 << OFF_SHOCK);
            else packedFacts &= ~(1 << OFF_SHOCK);
            conditionShockDetected(_shock);
        }
    }

    // ==========================================
    // 2. BASE DE REGRAS (Rule Base - RB)
    // ==========================================

    // --- Getters Internos (Evitam SLOAD redundante) ---
    function isDoorOpen() internal view returns (bool) { return ((packedFacts >> OFF_DOOR) & 1) == 1; }
    function getTemp() internal view returns (int8) { return int8(uint8((packedFacts >> OFF_TEMP) & 0xFF)); }

    // --- Premissas e Condições ---
    function premiseTempCritical(int8 _temp) internal {
        if (_temp > -50) conditionTempAndDoor(_temp, isDoorOpen());
    }

    function premiseTempHigh(int8 _temp) internal {
        if (_temp > -40) ruleWarning("Temp high");
    }

    function premiseDoorOpen(bool _door) internal {
        if (_door) conditionTempAndDoor(getTemp(), _door);
    }

    function conditionTempAndDoor(int8 _temp, bool _door) internal {
        if (_temp > -50 && _door) ruleCritical("Temp crit & Door open");
    }

    function conditionRouteDeviated(bool _route) internal { if (_route) ruleWarning("Route deviated"); }
    function conditionHumidityHigh(uint8 _hum) internal { if (_hum > 80) ruleWarning("Humidity high"); }
    function conditionPressureLow(uint16 _pres) internal { if (_pres < 950) ruleWarning("Pressure low"); }
    function conditionLightHigh(uint16 _light) internal { if (_light > 1000) ruleWarning("Light high"); }
    function conditionVibrationDetected(uint8 _vib) internal { if (_vib > 5) ruleWarning("Vibration"); }
    function conditionCO2High(uint16 _co2) internal { if (_co2 > 2000) ruleWarning("CO2 high"); }
    function conditionBatteryLow(uint8 _bat) internal { if (_bat < 20) ruleWarning("Battery low"); }
    function conditionShockDetected(bool _shock) internal { if (_shock) ruleWarning("Shock detected"); }

    // --- Regras e Ações ---
    function ruleCritical(string memory _msg) internal { emit InstigationTriggered(_msg); }
    function ruleWarning(string memory _msg) internal { emit InstigationTriggered(_msg); }
}

contracts/PONHyperFused.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title PONHyperFusedLogistics (PHF)
 * @author Matheus "San" de Camargo Marques
 * @notice Implementação Final para Tese de Doutorado: Bit-Packing + Yul + EIP-1153.
 */
contract PONHyperFusedLogistics {
    // Slot 0: Estado Persistente (Bit-Packed)
    // Layout: [Reserva: 173][Shock:1][Bat:8][CO2:16][Vib:8][Light:16][Pres:16][Hum:8][Route:1][Door:1][Temp:8]
    uint256 private packedFacts;

    // Slot Transiente (EIP-1153): Dirty-Mask para rastrear deltas por transação
    // Slot literal para EIP-1153 (keccak256("pon.hyperfused.dirty_mask"))
    bytes32 private constant DIRTY_MASK_SLOT = 0xb94d4bb16ee2057a0f1dbc2eb186c5e6831f88891da96b5b733f1c9363346d51;

    event InstigationTriggered(string message);

    /**
     * @notice Atualização em Lote com Inferência por Máscara de Bits
     */
    function updateLogistics(
        int8 _temp, bool _door, bool _route, uint8 _hum, 
        uint16 _pres, uint16 _light, uint8 _vib, uint16 _co2, 
        uint8 _bat, bool _shock
    ) external {
        assembly {
            // 1. CARREGAR ESTADO ATUAL
            let currentPacked := sload(0)
            let newPacked := currentPacked
            let dirtyMask := 0 

            // --- SEÇÃO DE DETECÇÃO DE DELTA (10 SENSORES) ---

            // [TEMP: bits 0-7] - Mask Bit 0 (0x01)
            let oldTemp := and(currentPacked, 0xFF)
            if iszero(eq(and(_temp, 0xFF), oldTemp)) {
                newPacked := or(and(newPacked, not(0xFF)), and(_temp, 0xFF))
                dirtyMask := or(dirtyMask, 0x01) 
            }

            // [DOOR: bit 8] - Mask Bit 1 (0x02)
            let newDoor := iszero(iszero(_door))
            if iszero(eq(newDoor, and(shr(8, currentPacked), 0x01))) {
                newPacked := or(and(newPacked, not(shl(8, 0x01))), shl(8, newDoor))
                dirtyMask := or(dirtyMask, 0x02)
            }

            // [ROUTE: bit 9] - Mask Bit 2 (0x04)
            let newRoute := iszero(iszero(_route))
            if iszero(eq(newRoute, and(shr(9, currentPacked), 0x01))) {
                newPacked := or(and(newPacked, not(shl(9, 0x01))), shl(9, newRoute))
                dirtyMask := or(dirtyMask, 0x04)
            }

            // [HUMIDITY: bits 10-17] - Mask Bit 3 (0x08)
            if iszero(eq(and(_hum, 0xFF), and(shr(10, currentPacked), 0xFF))) {
                newPacked := or(and(newPacked, not(shl(10, 0xFF))), shl(10, and(_hum, 0xFF)))
                dirtyMask := or(dirtyMask, 0x08)
            }

            // [PRESSURE: bits 18-33] - Mask Bit 4 (0x10)
            if iszero(eq(and(_pres, 0xFFFF), and(shr(18, currentPacked), 0xFFFF))) {
                newPacked := or(and(newPacked, not(shl(18, 0xFFFF))), shl(18, and(_pres, 0xFFFF)))
                dirtyMask := or(dirtyMask, 0x10)
            }

            // [LIGHT: bits 34-49] - Mask Bit 5 (0x20)
            if iszero(eq(and(_light, 0xFFFF), and(shr(34, currentPacked), 0xFFFF))) {
                newPacked := or(and(newPacked, not(shl(34, 0xFFFF))), shl(34, and(_light, 0xFFFF)))
                dirtyMask := or(dirtyMask, 0x20)
            }

            // [VIBRATION: bits 50-57] - Mask Bit 6 (0x40)
            if iszero(eq(and(_vib, 0xFF), and(shr(50, currentPacked), 0xFF))) {
                newPacked := or(and(newPacked, not(shl(50, 0xFF))), shl(50, and(_vib, 0xFF)))
                dirtyMask := or(dirtyMask, 0x40)
            }

            // [CO2: bits 58-73] - Mask Bit 7 (0x80)
            if iszero(eq(and(_co2, 0xFFFF), and(shr(58, currentPacked), 0xFFFF))) {
                newPacked := or(and(newPacked, not(shl(58, 0xFFFF))), shl(58, and(_co2, 0xFFFF)))
                dirtyMask := or(dirtyMask, 0x80)
            }

            // [BATTERY: bits 74-81] - Mask Bit 8 (0x100)
            if iszero(eq(and(_bat, 0xFF), and(shr(74, currentPacked), 0xFF))) {
                newPacked := or(and(newPacked, not(shl(74, 0xFF))), shl(74, and(_bat, 0xFF)))
                dirtyMask := or(dirtyMask, 0x100)
            }

            // [SHOCK: bit 82] - Mask Bit 9 (0x200)
            let newShock := iszero(iszero(_shock))
            if iszero(eq(newShock, and(shr(82, currentPacked), 0x01))) {
                newPacked := or(and(newPacked, not(shl(82, 0x01))), shl(82, newShock))
                dirtyMask := or(dirtyMask, 0x200)
            }

            // 2. PERSISTÊNCIA E GATING DE REGRAS
            if iszero(eq(dirtyMask, 0)) {
                sstore(0, newPacked)
                // Atribuir a constante a uma variável local Yul para garantir compatibilidade
                let slot := 0xb94d4bb16ee2057a0f1dbc2eb186c5e6831f88891da96b5b733f1c9363346d51
                tstore(slot, dirtyMask)

                // ==========================================
                // 3. MOTOR DE INFERÊNCIA PHF (10 REGRAS)
                // ==========================================

                // R1: Temp Critical (> -50) AND Door Open (Gate: bits 0 ou 1)
                if and(dirtyMask, 0x03) {
                    let tempVal := signextend(0, and(newPacked, 0xFF))
                    if and(sgt(tempVal, sub(0, 50)), and(shr(8, newPacked), 0x01)) {
                        _emitEvent("Critical: Temp/Door Violation", 27)
                    }
                }

                // R2: Humidity High (> 80) (Gate: bit 3)
                if and(dirtyMask, 0x08) {
                    if gt(and(shr(10, newPacked), 0xFF), 80) {
                        _emitEvent("Warning: Humidity High", 21)
                    }
                }

                // R3: Pressure Low (< 950) (Gate: bit 4)
                if and(dirtyMask, 0x10) {
                    if lt(and(shr(18, newPacked), 0xFFFF), 950) {
                        _emitEvent("Warning: Pressure Low", 20)
                    }
                }

                // R4: Light High (> 1000) (Gate: bit 5)
                if and(dirtyMask, 0x20) {
                    if gt(and(shr(34, newPacked), 0xFFFF), 1000) {
                        _emitEvent("Warning: Light High", 18)
                    }
                }

                // R5: Vibration Detected (> 5) (Gate: bit 6)
                if and(dirtyMask, 0x40) {
                    if gt(and(shr(50, newPacked), 0xFF), 5) {
                        _emitEvent("Warning: Vibration Detected", 26)
                    }
                }

                // R6: CO2 High (> 2000) (Gate: bit 7)
                if and(dirtyMask, 0x80) {
                    if gt(and(shr(58, newPacked), 0xFFFF), 2000) {
                        _emitEvent("Warning: CO2 High", 16)
                    }
                }

                // R7: Battery Low (< 20) (Gate: bit 8)
                if and(dirtyMask, 0x100) {
                    if lt(and(shr(74, newPacked), 0xFF), 20) {
                        _emitEvent("Warning: Battery Low", 19)
                    }
                }

                // R8: Shock Detected (Gate: bit 9)
                if and(dirtyMask, 0x200) {
                    if and(shr(82, newPacked), 0x01) {
                        _emitEvent("Alert: Shock Detected", 20)
                    }
                }

                // R9: Route Deviated (Gate: bit 2)
                if and(dirtyMask, 0x04) {
                    if and(shr(9, newPacked), 0x01) {
                        _emitEvent("Warning: Route Deviated", 22)
                    }
                }

                // R10: Temp High (> -40) (Gate: bit 0)
                if and(dirtyMask, 0x01) {
                    let tempVal := signextend(0, and(newPacked, 0xFF))
                    if sgt(tempVal, sub(0, 40)) {
                        _emitEvent("Warning: Temp High", 17)
                    }
                }
                // Clear the transient storage slot to avoid composability issues
                tstore(slot, 0)
            }

            function _emitEvent(msgStr, msgLen) {
                let signature := 0x8b8e0d165681992036c05d5d8d4c2d3d4e5f6a7b8c9d0e1f2a3b4c5d6e7f8a9b
                mstore(0x00, 0x20)
                mstore(0x20, msgLen)
                mstore(0x40, msgStr)
                log1(0x00, 0x60, signature)
            }
        }
    }
}

