// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract PONLogistics {
    // --- FATOS (Facts) ---
    int256 public factTemperature;
    bool public factDoorOpen;
    bool public factRouteDeviated;
    int256 public factHumidity;
    int256 public factPressure;
    int256 public factLight;
    int256 public factVibration;
    int256 public factCO2;
    int256 public factBattery;
    bool public factShockDetected;

    event ActionExecuted(string actionName);

    /**
     * @notice Atualização consolidada. Mantém a reatividade do PON avaliando 
     * regras apenas para os fatos que sofreram mutação.
     */
    function updateAll(
        int256 _temp, bool _door, bool _route, int256 _humidity, 
        int256 _pressure, int256 _light, int256 _vibration, 
        int256 _co2, int256 _battery, bool _shock
    ) external {

        // 1. Controle de Deltas em Memória (Evita duplo disparo)
        bool tempChanged = false;
        if (factTemperature != _temp) {
            factTemperature = _temp;
            tempChanged = true;
        }

        bool doorChanged = false;
        if (factDoorOpen != _door) {
            factDoorOpen = _door;
            doorChanged = true;
        }

        // 2. Avaliação e Notificação Direta (Fatos Simples)
        if (factRouteDeviated != _route) {
            factRouteDeviated = _route;
            notifyRuleRoute();
        }

        if (factHumidity != _humidity) {
            factHumidity = _humidity;
            notifyRuleHumidityHigh();
        }

        if (factPressure != _pressure) {
            factPressure = _pressure;
            notifyRulePressureLow();
        }

        if (factLight != _light) {
            factLight = _light;
            notifyRuleLightHigh();
        }

        if (factVibration != _vibration) {
            factVibration = _vibration;
            notifyRuleVibrationDetected();
        }

        if (factCO2 != _co2) {
            factCO2 = _co2;
            notifyRuleCO2High();
        }

        if (factBattery != _battery) {
            factBattery = _battery;
            notifyRuleBatteryLow();
        }

        if (factShockDetected != _shock) {
            factShockDetected = _shock;
            notifyRuleShockDetected();
        }

        // 3. Resolução de Regras Compostas e Sobrepostas
        // Garante que a regra dependente de 2 fatos seja chamada apenas 1x
        if (tempChanged || doorChanged) {
            notifyRuleTempAndDoor();
        }

        if (tempChanged) {
            notifyRuleTempHigh();
        }
    }

    // --- ATUALIZAÇÃO DE FATOS E NOTIFICAÇÃO (Edge/Oracles chamam aqui) ---
    function updateFactTemperature(int256 _temp) external {
        if (factTemperature != _temp) {
            factTemperature = _temp;
            // Notifica cirurgicamente apenas as regras dependentes
            notifyRuleTempAndDoor();
            notifyRuleTempHigh();
        }
    }

    function updateFactDoor(bool _door) external {
        if (factDoorOpen != _door) {
            factDoorOpen = _door;
            notifyRuleTempAndDoor();
        }
    }

    function updateFactRoute(bool _route) external {
        if (factRouteDeviated != _route) {
            factRouteDeviated = _route;
            notifyRuleRoute();
        }
    }

    function updateFactHumidity(int256 _humidity) external {
        if (factHumidity != _humidity) {
            factHumidity = _humidity;
            notifyRuleHumidityHigh();
        }
    }

    function updateFactPressure(int256 _pressure) external {
        if (factPressure != _pressure) {
            factPressure = _pressure;
            notifyRulePressureLow();
        }
    }

    function updateFactLight(int256 _light) external {
        if (factLight != _light) {
            factLight = _light;
            notifyRuleLightHigh();
        }
    }

    function updateFactVibration(int256 _vibration) external {
        if (factVibration != _vibration) {
            factVibration = _vibration;
            notifyRuleVibrationDetected();
        }
    }

    function updateFactCO2(int256 _co2) external {
        if (factCO2 != _co2) {
            factCO2 = _co2;
            notifyRuleCO2High();
        }
    }

    function updateFactBattery(int256 _battery) external {
        if (factBattery != _battery) {
            factBattery = _battery;
            notifyRuleBatteryLow();
        }
    }

    function updateFactShock(bool _shock) external {
        if (factShockDetected != _shock) {
            factShockDetected = _shock;
            notifyRuleShockDetected();
        }
    }

    // --- REGRAS (Rules - Avaliação Lógica Isolada) ---
    function notifyRuleTempAndDoor() internal {
        if (factTemperature > -50 && factDoorOpen) {
            actionTriggerAlert("Critical: Temp high and door open");
        }
    }

    function notifyRuleTempHigh() internal {
        if (factTemperature > -40) {
            actionTriggerAlert("Warning: Temp too high");
        }
    }

    function notifyRuleRoute() internal {
        if (factRouteDeviated) {
            actionTriggerAlert("Warning: Route deviated");
        }
    }

    function notifyRuleHumidityHigh() internal {
        if (factHumidity > 80) {
            actionTriggerAlert("Warning: Humidity too high");
        }
    }

    function notifyRulePressureLow() internal {
        if (factPressure < 950) {
            actionTriggerAlert("Warning: Pressure too low");
        }
    }

    function notifyRuleLightHigh() internal {
        if (factLight > 1000) {
            actionTriggerAlert("Warning: Light too high");
        }
    }

    function notifyRuleVibrationDetected() internal {
        if (factVibration > 5) {
            actionTriggerAlert("Warning: Vibration detected");
        }
    }

    function notifyRuleCO2High() internal {
        if (factCO2 > 2000) {
            actionTriggerAlert("Warning: CO2 too high");
        }
    }

    function notifyRuleBatteryLow() internal {
        if (factBattery < 20) {
            actionTriggerAlert("Warning: Battery low");
        }
    }

    function notifyRuleShockDetected() internal {
        if (factShockDetected) {
            actionTriggerAlert("Warning: Shock detected");
        }
    }

    // --- AÇÕES (Actions - Side Effects On-Chain) ---
    function actionTriggerAlert(string memory message) internal {
        emit ActionExecuted(message);
    }
}

contracts/ShortCircuitPONLogistics.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title ShortCircuitPONLogistics
 * @notice Implementação completa focada em Logic Gating e Short-Circuiting
 * @author Matheus "San" de Camargo Marques
 */
contract ShortCircuitPONLogistics {

    // --- BASE DE FATOS (Estado) ---
    int256 private temp;
    bool    private door;
    bool    private route;
    uint256 private hum;
    uint256 private pres;
    uint256 private light;
    uint256 private vib;
    uint256 private co2;
    uint256 private bat;
    bool    private shock;

    event InstigationTriggered(string actionName);

    /**
     * @notice Atualiza todos os sensores em lote aplicando a filosofia de Short-Circuit.
     * @dev Usa a avaliação preguiçosa (lazy evaluation) do Solidity para abortar 
     * processamentos desnecessários o mais cedo possível.
     */
    function updateAllShortCircuit(
        int256 _temp, bool _door, bool _route, uint256 _hum, 
        uint256 _pres, uint256 _light, uint256 _vib, uint256 _co2, 
        uint256 _bat, bool _shock
    ) external {
        // Variáveis de controle para a regra composta
        bool tempChanged = false;
        bool doorChanged = false;

        // [GATE: TEMP]
        // Se não mudou, pula o SSTORE e pula a avaliação de Temp High
        if (temp != _temp) {
            temp = _temp;
            tempChanged = true;
            if (_temp > -40) ruleWarning("Temp High");
        }

        // [GATE: DOOR]
        if (door != _door) {
            door = _door;
            doorChanged = true;
        }

        // [GATE: REGRA COMPOSTA (Temp + Door)]
        // O Ápice do Short-Circuiting:
        // 1º Gate: Mudou algo? (Se false, a EVM para aqui)
        // 2º Gate: A porta está aberta? (Booleano na memória é ultra barato)
        // 3º Gate: A temperatura passou do limite? (Matemática, fica por último)
        if ((tempChanged || doorChanged) && _door && _temp > -50) {
            ruleCritical("Violation: Door open with high temp");
        }

        // [GATE: ROUTE]
        if (route != _route) {
            route = _route;
            if (_route) ruleWarning("Route Deviated");
        }

        // [GATE: HUMIDITY]
        if (hum != _hum) {
            hum = _hum;
            if (_hum > 80) ruleWarning("Humidity High");
        }

        // [GATE: PRESSURE]
        if (pres != _pres) {
            pres = _pres;
            if (_pres < 950) ruleWarning("Pressure Low");
        }

        // [GATE: LIGHT]
        if (light != _light) {
            light = _light;
            if (_light > 1000) ruleWarning("Light High");
        }

        // [GATE: VIBRATION]
        if (vib != _vib) {
            vib = _vib;
            if (_vib > 5) ruleWarning("Vibration Detected");
        }

        // [GATE: CO2]
        if (co2 != _co2) {
            co2 = _co2;
            if (_co2 > 2000) ruleWarning("CO2 High");
        }

        // [GATE: BATTERY]
        if (bat != _bat) {
            bat = _bat;
            if (_bat < 20) ruleWarning("Battery Low");
        }

        // [GATE: SHOCK]
        if (shock != _shock) {
            shock = _shock;
            if (_shock) ruleWarning("Shock Detected");
        }
    }

    // ==========================================
    // 1. MÉTODOS DE ATUALIZAÇÃO (GATEKEEPERS)
    // ==========================================

    // Regra de Ouro 1: Early Return se o valor não mudou (Evita SSTORE)
    // Regra de Ouro 2: Gatilhos condicionais (Evita chamadas de função inúteis)

    function methodUpdateTemperature(int256 _temp) external {
        if (temp == _temp) return; 
        temp = _temp;
        // Portão: Só avalia premissas se o valor entrar na zona de risco
        if (_temp > -50) premiseTempCritical(_temp);
        if (_temp > -40) ruleWarning("Temp High");
    }

    function methodUpdateDoor(bool _door) external {
        if (door == _door) return;
        door = _door;
        // Portão: Se a porta fechou (false), não há risco de violação conjunta
        if (_door) conditionTempAndDoor(temp, _door);
    }

    function methodUpdateRoute(bool _route) external {
        if (route == _route) return;
        route = _route;
        if (_route) ruleWarning("Route Deviated");
    }

    function methodUpdateHumidity(uint256 _hum) external {
        if (hum == _hum) return;
        hum = _hum;
        if (_hum > 80) ruleWarning("Humidity High");
    }

    function methodUpdatePressure(uint256 _pres) external {
        if (pres == _pres) return;
        pres = _pres;
        if (_pres < 950) ruleWarning("Pressure Low");
    }

    function methodUpdateLight(uint256 _light) external {
        if (light == _light) return;
        light = _light;
        if (_light > 1000) ruleWarning("Light High");
    }

    function methodUpdateVibration(uint256 _vib) external {
        if (vib == _vib) return;
        vib = _vib;
        if (_vib > 5) ruleWarning("Vibration Detected");
    }

    function methodUpdateCO2(uint256 _co2) external {
        if (co2 == _co2) return;
        co2 = _co2;
        if (_co2 > 2000) ruleWarning("CO2 High");
    }

    function methodUpdateBattery(uint256 _bat) external {
        if (bat == _bat) return;
        bat = _bat;
        if (_bat < 20) ruleWarning("Battery Low");
    }

    function methodUpdateShock(bool _shock) external {
        if (shock == _shock) return;
        shock = _shock;
        if (_shock) ruleWarning("Shock Detected");
    }

    // ==========================================
    // 2. BASE DE REGRAS (LOGIC GATING)
    // ==========================================

    /**
     * @dev Exemplo mestre de Short-Circuiting.
     * O booleano 'door' é verificado ANTES da comparação numérica 'temp'.
     * Se 'door' for false, a EVM ignora a comparação de temperatura.
     */
    function conditionTempAndDoor(int256 _currentTemp, bool _currentDoor) internal {
        // Portão: [Booleano (Barato)] && [Comparação (Médio)]
        if (_currentDoor && _currentTemp > -50) {
            ruleCritical("Violation: Door open with high temp");
        }
    }

    function premiseTempCritical(int256 _t) internal {
        // Só chama a condição se houver um portão aberto (porta aberta)
        if (door) conditionTempAndDoor(_t, door);
    }

    // ==========================================
    // 3. REGRAS E AÇÕES
    // ==========================================

    function ruleCritical(string memory _m) internal {
        emit InstigationTriggered(_m);
    }

    function ruleWarning(string memory _m) internal {
        emit InstigationTriggered(_m);
    }
}

